/**
 * check:contract — validate the REAL exported JSON files (dashboard/public/data/)
 * against the Zod schemas in src/types/contract.ts.
 *
 * Run from dashboard/:  npm run check:contract
 * Exit code 0 = the six files parse; 1 = at least one contract violation.
 *
 * The exported files are gitignored (regenerated by scripts/export_json.py),
 * so this script fails loudly when they are missing — the dashboard has no
 * data story without an export.
 */

import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

import {
  AlertsSchema,
  GoalsSchema,
  HistorySchema,
  LatestSchema,
  PerformanceSchema,
  XirrSchema,
} from '../src/types/contract'

const DATA_DIR = resolve(import.meta.dirname, '../public/data')

function load(file: string): unknown {
  const path = resolve(DATA_DIR, file)
  return JSON.parse(readFileSync(path, 'utf8')) as unknown
}

function report(file: string, check: () => void): boolean {
  try {
    check()
    return true
  } catch (err) {
    console.error(`FAIL ${file}: ${err instanceof Error ? err.message : String(err)}`)
    return false
  }
}

let ok = true

ok = report('latest.json', () => {
  const latest = LatestSchema.parse(load('latest.json'))
  const withCost = latest.holdings.filter((h) => h.returnPct !== null).length
  const sum = Object.values(latest.allocation.byGeography).reduce((a, b) => a + b, 0)
  console.log(
    `ok   latest.json: asOf=${latest.asOf} valueBase=${latest.totals.valueBase}` +
      ` dayPnl=${latest.totals.dayPnl} holdings=${latest.holdings.length}` +
      ` (${withCost} with cost basis) byGeography=${JSON.stringify(latest.allocation.byGeography)}` +
      ` allocSum=${sum.toFixed(2)}%`,
  )
  if (Math.abs(sum - 100) > 0.5) {
    throw new Error(`geography allocation sums to ${sum.toFixed(2)}%, expected ~100%`)
  }
})

ok = report('history.json', () => {
  const history = HistorySchema.parse(load('history.json'))
  const len = history.dates.length
  const arraysOk =
    history.portfolioValueBase.length === len &&
    Object.values(history.byGeography).every((a) => a.length === len) &&
    Object.values(history.byPlatform).every((a) => a.length === len)
  console.log(
    `ok   history.json: ${len} dates (${history.dates[0]} .. ${history.dates[len - 1]})` +
      ` platforms=${Object.keys(history.byPlatform).length}` +
      ` geographies=${Object.keys(history.byGeography).length} aligned=${arraysOk}`,
  )
  if (!arraysOk) throw new Error('series arrays not aligned with dates')
}) && ok

ok = report('alerts.json', () => {
  const alerts = AlertsSchema.parse(load('alerts.json'))
  const bySeverity = new Map<string, number>()
  for (const a of alerts.alerts) bySeverity.set(a.severity, (bySeverity.get(a.severity) ?? 0) + 1)
  console.log(
    `ok   alerts.json: generatedAt=${alerts.generatedAt} alerts=${alerts.alerts.length}` +
      ` severities=${JSON.stringify(Object.fromEntries(bySeverity))}`,
  )
}) && ok

ok = report('xirr.json', () => {
  const xirr = XirrSchema.parse(load('xirr.json'))
  const accounts = Object.entries(xirr.perAccount)
  const withRate = accounts.filter(([, e]) => e.xirrPct !== null).length
  console.log(
    `ok   xirr.json: asOf=${xirr.asOf} accounts=${accounts.length}` +
      ` (${withRate} with xirr, ${accounts.length - withRate} null) estimated=${xirr.estimated}`,
  )
}) && ok

ok = report('performance.json', () => {
  const perf = PerformanceSchema.parse(load('performance.json'))
  const len = perf.daily.length
  const latest = perf.daily[len - 1]
  if (!latest) throw new Error('daily array is empty — no performance days exported')
  const sumGeo = Object.values(latest.attribution.byGeography).reduce((a, b) => a + b, 0)
  const sumPlat = Object.values(latest.attribution.byPlatform).reduce((a, b) => a + b, 0)
  const sumAc = Object.values(latest.attribution.byAssetClass).reduce((a, b) => a + b, 0)
  const revalCount = latest.revaluationEvents.length
  console.log(
    `ok   performance.json: asOf=${perf.asOf} days=${len} latest=${latest.date}` +
      ` dayPnlBase=${latest.dayPnlBase} revaluationEvents=${revalCount}` +
      ` attSum(geo=${sumGeo.toFixed(2)}, platform=${sumPlat.toFixed(2)}, assetClass=${sumAc.toFixed(2)})`,
  )
  // M3.5 reconciliation invariant: each attribution dimension sums to the day's
  // dayPnlBase (within rounding tolerance of the exported precision).
  const dims: Array<[string, number]> = [
    ['byGeography', sumGeo],
    ['byPlatform', sumPlat],
    ['byAssetClass', sumAc],
  ]
  for (const [dim, sum] of dims) {
    if (Math.abs(sum - latest.dayPnlBase) > 0.5) {
      throw new Error(
        `attribution.${dim} sums to ${sum.toFixed(2)}, expected ≈ dayPnlBase ${latest.dayPnlBase} (M3.5 reconciliation invariant)`,
      )
    }
  }
}) && ok

ok = report('goals.json', () => {
  const goals = GoalsSchema.parse(load('goals.json'))
  const crossed = goals.goals.filter((g) => g.crossedAt !== null).length
  const ids = new Set(goals.goals.map((g) => g.id))
  console.log(
    `ok   goals.json: asOf=${goals.asOf} valueBase=${goals.valueBase}` +
      ` goals=${goals.goals.length} (${crossed} crossed)`,
  )
  // The DB id is the PATCH/DELETE target and the UI's crossing-ack key —
  // duplicates would silently break both.
  if (ids.size !== goals.goals.length) throw new Error('duplicate goal ids')
}) && ok

if (!ok) {
  console.error('\nCONTRACT CHECK FAILED — the exported JSONs violate the Zod schemas.')
  process.exit(1)
}
console.log('\nContract check passed: all six files parse against the schemas.')